create or replace function public.validate_assignment_submission_bounds() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare v_due timestamptz; v_allow boolean; v_close timestamptz; v_max numeric; begin select due_at,allow_late,late_close_at,max_score into v_due,v_allow,v_close,v_max from public.assignments where id=new.assignment_id; if v_max is null then raise exception 'Assignment not found'; end if; if new.score is not null and new.score>v_max then raise exception 'Score exceeds assignment maximum'; end if; if new.score is not null and new.score<0 then raise exception 'Score cannot be negative'; end if; if auth.uid() is not null and public.current_app_role()='STUDENT' and tg_op='INSERT' then if new.student_id<>auth.uid() then raise exception 'Submission owner must be signed-in student'; end if; if now()<=v_due and new.status<>'SUBMITTED' then raise exception 'Submission status is not valid for current time'; end if; if now()>v_due and (not v_allow or now()>v_close or new.status<>'LATE') then raise exception 'Late submission is not allowed'; end if; end if; return new; end $$;
create trigger assignment_submission_bounds before insert or update of assignment_id,score on public.assignment_submissions for each row execute function public.validate_assignment_submission_bounds();
create or replace function public.validate_rubric_score_bound() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare v_max numeric; begin select max_score into v_max from public.rubric_criteria where id=new.criterion_id; if v_max is null or new.score>v_max then raise exception 'Rubric score exceeds criterion maximum'; end if; return new; end $$;
create trigger rubric_score_bounds before insert or update of criterion_id,score on public.rubric_scores for each row execute function public.validate_rubric_score_bound();
